
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_bc95_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_bc95", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.688837812680212e-02, -5.648527167033252e-02, -5.590171726929928e-02, -5.505438271395535e-02, -5.381841329702644e-02, -5.200312168052357e-02, -4.931016401284153e-02, -4.526659639789462e-02, -3.919021169341416e-02, -3.083085244660613e-02, -2.557933240109131e-02, -5.357551024816917e-02, -3.740050986053984e-02, -2.401933122584244e-02, -1.424227948515695e-02, -4.854873620078221e-03, -5.246386561031910e-04, -1.122621147137454e-05, -3.409282771065865e-08, -1.520358690034878e-11]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


